namespace IQ2i\HerseBundle\Bridge\Moka\Mapping;

use Doctrine\ORM\Mapping\Builder\ClassMetadataBuilder;
use Moka\Cms\Bridge\Doctrine\Mapping\Mapper\UserMapper;

/**
 * Maps the columns of the second factor on the user class generated by Moka.
 *
 * @internal
 */
final class TwoFactorUserMapper extends UserMapper
{
    public function loadMetadataForClass(string $className, ClassMetadataBuilder $builder): void
    {
        parent::loadMetadataForClass($className, $builder);

        $builder->createField('emailAuthEnabled', 'boolean')->option('default', false)->build();
        $builder->addField('authCode', 'string', ['nullable' => true]);
    }
}
